public enum PhonePastEnding {
    public static func words(_ ending: PhoneJSON) -> String {
        let label = ending["label"].text ?? "an option"
        return switch (ending["how"].text ?? "unknown", ending["by"].text ?? "captain") {
        case ("chose", "firstmate"): "Your first mate chose \(label)"
        case ("chose", "crewmate"): "Its crewmate chose \(label)"
        case ("chose", _): "You chose \(label)"
        case ("dismissed", _): "Closed without choosing"
        case ("author-withdrawal", _): "Withdrawn by its author"
        case ("host-withdrawal", _): "Taken down by the app"
        case ("task-retired", _): "Taken down when the task ended"
        case ("duplicate", _): "Closed as a duplicate"
        case ("unknown", _): "Closed"
        default: "Closed"
        }
    }
}

public enum PhoneSSHCommand {
    public static let header = "infinitary-phone-link"
    public static let version = "1"
    public static let link = "/bin/sh -c 'h=infinitary-phone-link; set -- \"$INFINITARY_USER_DATA_DIR\" \"$HOME/Library/Application Support/infinitary\" \"${XDG_CONFIG_HOME:-$HOME/.config}/infinitary\" \"$HOME/.config/infinitary\" \"$HOME/Library/Application Support/infinitary-dev\" \"${XDG_CONFIG_HOME:-$HOME/.config}/infinitary-dev\"; d=; for c do if [ -n \"$c\" ] && [ -r \"$c/phone-door/key\" ] && [ -r \"$c/phone-door/address\" ]; then d=$c; break; fi; done; if [ -z \"$d\" ]; then for c in \"$@\" \"$HOME/Library/Application Support/firstmate-3000\" \"$HOME/.config/firstmate-3000\"; do l=$(readlink \"$c/SingletonLock\" 2>/dev/null) && [ -n \"$c\" ] && kill -0 \"${l##*-}\" 2>/dev/null && { echo \"$h 1 none too-old\"; exit 0; }; done; echo \"$h 1 none not-open\"; exit 0; fi; read -r a < \"$d/phone-door/address\"; case $a in 127.0.0.1:*) ;; *) echo \"$h 1 none not-open\"; exit 0 ;; esac; u=/usr/bin/curl; [ -x \"$u\" ] || u=$(command -v curl) || { echo \"$h 1 none no-curl\"; exit 0; }; r=$(\"$u\" -q -s --noproxy \"*\" --max-time 30 -X POST -H \"@$d/phone-door/key\" \"http://$a/phone-link\") || { echo \"$h 1 none not-open\"; exit 0; }; echo \"$r\"'"
    public static let placeKey = "/bin/sh -c 'h=infinitary-phone-link; umask 077; S=\"$HOME/.ssh\"; F=\"$S/authorized_keys\"; mkdir -p \"$S\" || exit 3; chmod go-w \"$S\" 2>/dev/null; touch \"$F\" || exit 3; chmod go-w \"$F\" 2>/dev/null; grep -qxF -- \"$1\" \"$F\" || { if [ -s \"$F\" ] && [ -n \"$(tail -c 1 \"$F\")\" ]; then echo >> \"$F\" || exit 3; fi; echo \"$1\" >> \"$F\" || exit 3; }; echo \"$h 1 placed\"' infinitary-phone-link"
    public static let placed = "infinitary-phone-link 1 placed"
    public static let notOpen = "not-open"
    public static let tooOld = "too-old"
    public static let noCurl = "no-curl"
}

